//! Borrowed engine inputs: scalar math reads the original element types, never
//! copies a cache into unmetered Vecs. Descriptors own no nested allocation.
use crate::types::{invalid, limit, stopped};
use crate::*;

#[derive(Debug, Clone, Copy)]
pub struct JobDashRange {
    pub segments: TableRange,
    pub joins: TableRange,
    pub grid_cells: JobBuffer<GridCell>,
    pub grid_refs: JobBuffer<u32>,
    pub grid_min_x: f64,
    pub grid_min_y: f64,
    pub grid_cell_size: f64,
    pub grid_columns: u16,
    pub grid_rows: u16,
}
#[derive(Debug, Clone, Copy)]
pub struct JobDashCache {
    pub segments: JobBuffer<DashSegment>,
    pub joins: JobBuffer<DashJoin>,
    pub shapes: JobBuffer<JobDashRange>,
    pub build_steps: usize,
}
#[derive(Clone, Copy)]
pub struct JobDashView<'a> {
    job: &'a RasterJob,
    pub segments: &'a [DashSegment],
    pub joins: &'a [DashJoin],
    pub shapes: &'a [JobDashRange],
}
impl RasterJob {
    pub fn dash_view(&self, cache: JobDashCache, control: &mut dyn WorkControl) -> Result<JobDashView<'_>> {
        control.checkpoint().map_err(stopped)?;
        if cache.build_steps > 1_000_000 {
            return Err(limit(LimitKind::DashCache));
        }
        self.require_pool(cache.segments, RasterPool::Dash)?;
        self.require_pool(cache.joins, RasterPool::Dash)?;
        self.require_pool(cache.shapes, RasterPool::Dash)?;
        let view = JobDashView {
            job: self,
            segments: self.slice(cache.segments)?,
            joins: self.slice(cache.joins)?,
            shapes: self.slice(cache.shapes)?,
        };
        view.validate(control)?;
        Ok(view)
    }
}
impl<'a> JobDashView<'a> {
    /// Resolves only same-job, still-live handles. A caller may retain descriptors
    /// across release, but can never dereference them without revalidation.
    pub fn grid(&self, range: &JobDashRange) -> Result<(&'a [GridCell], &'a [u32])> {
        self.job.require_pool(range.grid_cells, RasterPool::Grid)?;
        self.job.require_pool(range.grid_refs, RasterPool::Grid)?;
        Ok((
            self.job.slice(range.grid_cells)?,
            self.job.slice(range.grid_refs)?,
        ))
    }
    pub fn validate(&self, control: &mut dyn WorkControl) -> Result<()> {
        if self.shapes.len() > 65536 {
            return Err(limit(LimitKind::Shapes));
        }
        for segment in self.segments {
            control.charge(WorkKind::StrokeTest, 1).map_err(stopped)?;
            if ![segment.edge.a, segment.edge.b]
                .into_iter()
                .all(vexel_geometry::finite_point)
            {
                return Err(invalid(0));
            }
        }
        for join in self.joins {
            control.charge(WorkKind::StrokeTest, 1).map_err(stopped)?;
            if ![join.previous, join.vertex, join.next]
                .into_iter()
                .all(vexel_geometry::finite_point)
            {
                return Err(invalid(0));
            }
        }
        let (mut cell_count, mut ref_count) = (0usize, 0usize);
        for range in self.shapes {
            control.charge(WorkKind::StrokeTest, 1).map_err(stopped)?;
            range.segments.require(self.segments.len(), 0)?;
            range.joins.require(self.joins.len(), 0)?;
            let (cells, refs) = self.grid(range)?;
            cell_count = cell_count
                .checked_add(cells.len())
                .ok_or_else(crate::memory::arithmetic)?;
            ref_count = ref_count
                .checked_add(refs.len())
                .ok_or_else(crate::memory::arithmetic)?;
            if cell_count > 65536
                || ref_count > 1_000_000
                || range.grid_columns > 128
                || range.grid_rows > 128
            {
                return Err(limit(LimitKind::Grid));
            }
            if ![range.grid_min_x, range.grid_min_y, range.grid_cell_size]
                .into_iter()
                .all(f64::is_finite)
                || cells.len() != range.grid_columns as usize * range.grid_rows as usize
                || ((cells.is_empty()) != (range.grid_columns == 0 && range.grid_rows == 0))
                || (!cells.is_empty() && range.grid_cell_size <= 0.0)
            {
                return Err(invalid(0));
            }
            for cell in cells {
                control.charge(WorkKind::StrokeTest, 1).map_err(stopped)?;
                TableRange {
                    first: cell.first,
                    count: cell.count,
                }
                .require(refs.len(), 0)?;
            }
            for reference in refs {
                control.charge(WorkKind::StrokeTest, 1).map_err(stopped)?;
                let index = (*reference & !STROKE_GRID_JOIN_BIT) as usize;
                let allowed = if *reference & STROKE_GRID_JOIN_BIT != 0 {
                    range.joins
                } else {
                    range.segments
                };
                if index < allowed.first || index >= allowed.end().ok_or_else(crate::memory::arithmetic)? {
                    return Err(invalid(0));
                }
            }
        }
        control.checkpoint().map_err(stopped)
    }
}

/// Complete controlled capability; deliberately has NO blanket conversion from
/// KernelResources, no default paint, and no production placeholder implementation.
/// The coordinator implements every method from the actual paint/clip/stroke
/// engines. Variable loops must poll this exact control and propagate its error.
pub trait ControlledKernelResources {
    fn paint_sample(
        &self,
        paint: &Paint,
        stops: &[PaintStop],
        x: f64,
        y: f64,
        control: &mut dyn WorkControl,
    ) -> Result<[u8; 4]>;
    fn clip_contains(
        &self,
        view: SceneView<'_>,
        clip: ClipId,
        x: f64,
        y: f64,
        control: &mut dyn WorkControl,
    ) -> Result<bool>;
    fn clip_boundary_edges(
        &self,
        view: SceneView<'_>,
        clip: ClipId,
        visitor: &mut dyn FnMut(Edge) -> bool,
        control: &mut dyn WorkControl,
    ) -> Result<bool>;
    fn clip_work_counts(
        &self,
        view: SceneView<'_>,
        clip: ClipId,
        control: &mut dyn WorkControl,
    ) -> Result<ClipWorkCounts>;
    fn stroke_sample_work(
        &self,
        view: SceneView<'_>,
        shape: ShapeId,
        cache: JobDashView<'_>,
        x: f64,
        y: f64,
        control: &mut dyn WorkControl,
    ) -> Result<(usize, bool, bool)>;
}
/// Same scalar coordinates/lattice/edge data as SampleInput. The lower engine
/// changes its input type and propagates Result; its math and cost stay unchanged.
pub struct ControlledSampleInput<'a> {
    pub resources: &'a dyn ControlledKernelResources,
    pub active_edges: &'a [u32],
    pub local_edges: &'a [Edge],
    pub dash_seams: &'a [bool],
    pub dash_cache: JobDashView<'a>,
    pub px: f64,
    pub py: f64,
    pub paint_x: f64,
    pub paint_y: f64,
}
impl ControlledSampleInput<'_> {
    pub fn validate(&self, view: SceneView<'_>, control: &mut dyn WorkControl) -> Result<()> {
        self.dash_cache.job.validate_source(view.source_owner())?;
        if ![self.px, self.py, self.paint_x, self.paint_y]
            .into_iter()
            .all(f64::is_finite)
            || self.dash_seams.len() != self.local_edges.len()
        {
            return Err(invalid(0));
        }
        self.dash_cache.validate(control)?;
        for index in self.active_edges {
            control.charge(WorkKind::Edge, 1).map_err(stopped)?;
            if *index as usize >= view.edges.len() {
                return Err(invalid(0));
            }
        }
        Ok(())
    }
    /// No precharge or aftercharge substitute: the actual resource receives the
    /// caller's control, including while traversing stops/pattern samples.
    pub fn paint_sample(
        &self,
        paint: &Paint,
        stops: &[PaintStop],
        control: &mut dyn WorkControl,
    ) -> Result<[u8; 4]> {
        control.checkpoint().map_err(stopped)?;
        self.resources
            .paint_sample(paint, stops, self.paint_x, self.paint_y, control)
    }
}
/// Typed lower seam. Production implementations cannot accidentally accept the
/// legacy uncontrolled paint capability through this entrypoint.
pub trait ControlledSampleKernel {
    fn sample(
        &mut self,
        view: SceneView<'_>,
        shape: ShapeId,
        input: &ControlledSampleInput<'_>,
        control: &mut dyn WorkControl,
    ) -> Result<[u8; 4]>;
}
/// Lower index writers receive the same owning job as child/output/sample work.
pub trait ControlledIndexKernel {
    fn build_index(
        &mut self,
        view: SceneView<'_>,
        job: &mut RasterJob,
        mapping: ViewMapping,
        control: &mut dyn WorkControl,
    ) -> Result<JobRasterScratch>;
}
//! Allocation-free descriptors for the complete original scratch layout.
use crate::*;

#[derive(Debug, Clone, Copy)]
pub struct JobRasterScratch {
    pub bounds: JobBuffer<ShapeBounds>,
    pub boundary_bits: JobBuffer<u8>,
    pub scanline_events: JobBuffer<ScanlineEvent>,
    pub scanline_nodes: JobBuffer<ScanlineNode>,
    pub scanline_roots: JobBuffer<i32>,
    pub shape_events: JobBuffer<ShapeRowEvent>,
    pub shape_nodes: JobBuffer<ScanlineNode>,
    pub shape_offsets: JobBuffer<usize>,
    pub active_edges: JobBuffer<u32>,
    pub active_shapes: JobBuffer<u32>,
    pub eligible_shapes: JobBuffer<bool>,
    pub crossings: JobBuffer<FillCrossing>,
    pub intervals: JobBuffer<FillInterval>,
    pub pixel_runs: JobBuffer<PixelRun>,
    pub local_edges: JobBuffer<Edge>,
    pub dash_seams: JobBuffer<bool>,
    pub dash: JobDashCache,
    pub center_samples: JobBuffer<u8>,
    pub subpixel_samples: JobBuffer<u8>,
    pub stroke_cost: JobBuffer<usize>,
}
impl JobRasterScratch {
    /// Registers empty buffers only; the engine supplies each exact capacity to
    /// reserve. Every registration/payload/nested grid uses this same job ledger.
    /// Failure invalidates newly registered handles; metadata capacity is retained.
    pub fn new(job: &mut RasterJob, control: &mut dyn WorkControl) -> Result<Self> {
        let mark = job.resource_mark();
        let result = (|| {
            let dash = JobDashCache {
                segments: job.buffer(RasterPool::Dash, usize::MAX, control)?,
                joins: job.buffer(RasterPool::Dash, usize::MAX, control)?,
                shapes: job.buffer(RasterPool::Dash, 65536, control)?,
                build_steps: 0,
            };
            macro_rules! scratch {
                () => {
                    job.buffer(RasterPool::Scratch, usize::MAX, control)?
                };
            }
            Ok(Self {
                bounds: scratch!(),
                boundary_bits: job.buffer(RasterPool::Boundary, usize::MAX, control)?,
                scanline_events: scratch!(),
                scanline_nodes: scratch!(),
                scanline_roots: scratch!(),
                shape_events: scratch!(),
                shape_nodes: scratch!(),
                shape_offsets: scratch!(),
                active_edges: scratch!(),
                active_shapes: scratch!(),
                eligible_shapes: scratch!(),
                crossings: scratch!(),
                intervals: scratch!(),
                pixel_runs: scratch!(),
                local_edges: scratch!(),
                dash_seams: scratch!(),
                dash,
                center_samples: scratch!(),
                subpixel_samples: scratch!(),
                stroke_cost: scratch!(),
            })
        })();
        if result.is_err() {
            job.rollback_resources(mark)?;
        }
        result
    }
    fn require_distinct(&self) -> Result<()> {
        let identities = [
            self.bounds.identity(),
            self.boundary_bits.identity(),
            self.scanline_events.identity(),
            self.scanline_nodes.identity(),
            self.scanline_roots.identity(),
            self.shape_events.identity(),
            self.shape_nodes.identity(),
            self.shape_offsets.identity(),
            self.active_edges.identity(),
            self.active_shapes.identity(),
            self.eligible_shapes.identity(),
            self.crossings.identity(),
            self.intervals.identity(),
            self.pixel_runs.identity(),
            self.local_edges.identity(),
            self.dash_seams.identity(),
            self.dash.segments.identity(),
            self.dash.joins.identity(),
            self.dash.shapes.identity(),
            self.center_samples.identity(),
            self.subpixel_samples.identity(),
            self.stroke_cost.identity(),
        ];
        for (i, id) in identities.iter().enumerate() {
            if identities[..i].contains(id) {
                return Err(crate::types::invalid(0));
            }
        }
        Ok(())
    }
    // Fixed set of descriptor fields; cleanup does not depend on work control.
    fn require_roles(&self, job: &RasterJob) -> Result<()> {
        macro_rules! scratch { ($($field:ident),* $(,)?) => { $(
            job.require_pool(self.$field, RasterPool::Scratch)?;
        )* }; }
        scratch!(
            bounds,
            scanline_events,
            scanline_nodes,
            scanline_roots,
            shape_events,
            shape_nodes,
            shape_offsets,
            active_edges,
            active_shapes,
            eligible_shapes,
            crossings,
            intervals,
            pixel_runs,
            local_edges,
            dash_seams,
            center_samples,
            subpixel_samples,
            stroke_cost
        );
        job.require_pool(self.boundary_bits, RasterPool::Boundary)?;
        job.require_pool(self.dash.segments, RasterPool::Dash)?;
        job.require_pool(self.dash.joins, RasterPool::Dash)?;
        job.require_pool(self.dash.shapes, RasterPool::Dash)?;
        Ok(())
    }
    /// Check handle liveness and allocation roles before lower index/sample use.
    pub fn validate(&self, job: &RasterJob, control: &mut dyn WorkControl) -> Result<()> {
        self.require_distinct()?;
        control.checkpoint().map_err(crate::types::stopped)?;
        self.require_roles(job)?;
        job.dash_view(self.dash, control)?;
        Ok(())
    }
    /// Explicit early release. Job Drop also destroys all resources, including
    /// per-shape grids which can be shared by descriptors and remain job-owned.
    /// Individual releases reject stale/double handles; no recursive ownership.
    pub fn release(self, job: &mut RasterJob) -> Result<()> {
        // Validate every token first, so a mismatched descriptor changes nothing.
        macro_rules! each {
            ($method:ident) => {{
                job.$method(self.bounds)?;
                job.$method(self.boundary_bits)?;
                job.$method(self.scanline_events)?;
                job.$method(self.scanline_nodes)?;
                job.$method(self.scanline_roots)?;
                job.$method(self.shape_events)?;
                job.$method(self.shape_nodes)?;
                job.$method(self.shape_offsets)?;
                job.$method(self.active_edges)?;
                job.$method(self.active_shapes)?;
                job.$method(self.eligible_shapes)?;
                job.$method(self.crossings)?;
                job.$method(self.intervals)?;
                job.$method(self.pixel_runs)?;
                job.$method(self.local_edges)?;
                job.$method(self.dash_seams)?;
                job.$method(self.dash.segments)?;
                job.$method(self.dash.joins)?;
                job.$method(self.dash.shapes)?;
                job.$method(self.center_samples)?;
                job.$method(self.subpixel_samples)?;
                job.$method(self.stroke_cost)?;
            }};
        }
        self.require_distinct()?;
        self.require_roles(job)?;
        each!(capacity);
        each!(release);
        Ok(())
    }
//! Owning job allocations. Handles never own or expose a Vec or a lease.
use crate::memory::{arithmetic, bytes};
use crate::types::{invalid, limit, stopped};
use crate::*;
use std::marker::PhantomData;

/// Copy-only, allocation-free scalar records supported by the job arena.
/// Sealed: nested heap payloads cannot bypass accounting through an element.
pub trait JobElement: Copy + private::Element {}
#[derive(Debug, PartialEq, Eq)]
pub struct JobBuffer<T> {
    owner: u64,
    slot: usize,
    serial: u64,
    marker: PhantomData<T>,
}
impl<T> JobBuffer<T> {
    pub(crate) fn identity(self) -> (u64, usize, u64) {
        (self.owner, self.slot, self.serial)
    }
}
impl<T> Copy for JobBuffer<T> {}
impl<T> Clone for JobBuffer<T> {
    fn clone(&self) -> Self {
        *self
    }
}

/// Reference caps apply to retained actual capacity, including nested grid data.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum RasterPool {
    Scratch,
    Dash,
    Grid,
    Boundary,
    Output,
    GroupScratch,
}
impl RasterPool {
    fn cap(self) -> usize {
        match self {
            Self::Scratch => usize::MAX,
            Self::GroupScratch => 64 * 1024 * 1024,
            Self::Dash => 16 * 1024 * 1024,
            Self::Grid => 16 * 1024 * 1024,
            Self::Boundary => usize::MAX, // original cap is marking WORK, not bits
            Self::Output => usize::MAX,
        }
    }
    fn error(self) -> Diagnostic {
        limit(match self {
            Self::Scratch | Self::GroupScratch => LimitKind::Scratch,
            Self::Dash => LimitKind::DashCache,
            Self::Grid => LimitKind::Grid,
            Self::Boundary => LimitKind::Scratch,
            Self::Output => LimitKind::ReservedBytes,
        })
    }
}
struct Slot {
    serial: u64,
    data: private::Storage,
    lease: AllocationLease,
    pool: RasterPool,
    cap: usize,
    active: bool,
    next_free: Option<usize>,
    boundary_work: usize,
}
/// The sole owner of every buffer. Moving/copying a handle never transfers data.
/// Drop destroys all data and the ledger; no caller release or Drop allocation.
pub struct RasterJob {
    ledger: ChargeLedger,
    slots: Vec<Slot>,
    metadata: Option<AllocationLease>,
    free: Option<usize>,
    next: u64,
