    vexel_scene::Diagnostic {
        kind: match stop {
            vexel_scene::Stop::Canceled => vexel_scene::ErrorKind::Canceled,
            vexel_scene::Stop::Limit => vexel_scene::ErrorKind::Limit(vexel_scene::LimitKind::Work),
