pub fn build_dash_cache(
    view: SceneView<'_>,
    local_edges: &[Edge],
    seams: &[bool],
    control: &mut dyn WorkControl,
) -> Result<DashCache> {
    let mut c = DashCache::default();
    let n = view.shapes.len();
    let range_bytes = n
        .checked_mul(std::mem::size_of::<DashRange>())
        .ok_or_else(limit)?;
    if range_bytes > DASH_CACHE_BYTE_LIMIT {
        return Err(limit());
    }
    reserve(&mut c.shapes, n)?;
    if cache_used(&c).is_none_or(|used| used > DASH_CACHE_BYTE_LIMIT) {
        return Err(limit());
    }
    for (i, s) in view.shapes.iter().enumerate() {
        let start_s = c.segments.len();
        let start_j = c.joins.len();
        if s.stroke.rgba[3] != 0 && s.stroke.width > 0.0 {
            let d = s
                .stroke
                .dash_values
                .slice(view.dash_values)
                .ok_or_else(limit)?;
            if !s
                .subpaths
                .slice(view.path_subpaths)
                .ok_or_else(limit)?
                .is_empty()
            {
                for (si, p) in s
                    .subpaths
                    .slice(view.path_subpaths)
                    .unwrap()
                    .iter()
                    .enumerate()
                {
                    let seam = seams
                        .get(n + s.subpaths.first + si)
                        .copied()
                        .unwrap_or(false);
                    if d.is_empty() {
                        build_solid(
                            &mut c,
                            &s.stroke,
                            local_edges,
                            p.first_edge,
                            p.edge_count,
                            p.closed,
                            true,
                            control,
                        )?
                    } else {
                        build_dashed(
                            &mut c,
                            &s.stroke,
                            d,
                            local_edges,
                            p.first_edge,
                            p.edge_count,
                            p.closed,
                            true,
                            seam,
                            control,
                        )?
                    }
                }
            } else {
                let seam = seams.get(i).copied().unwrap_or(false);
                if d.is_empty() {
                    build_solid(
                        &mut c,
                        &s.stroke,
                        local_edges,
                        s.edges.first,
                        s.edges.count,
                        s.stroke_closed,
                        s.filled,
                        control,
                    )?
                } else {
                    build_dashed(
                        &mut c,
                        &s.stroke,
                        d,
                        local_edges,
                        s.edges.first,
                        s.edges.count,
                        s.stroke_closed,
                        s.filled,
                        seam,
                        control,
                    )?
                }
            }
        }
        c.shapes.push(DashRange {
            segments: vexel_scene::TableRange {
                first: start_s,
                count: c.segments.len() - start_s,
            },
            joins: vexel_scene::TableRange {
                first: start_j,
                count: c.joins.len() - start_j,
            },
            grid_cells: Vec::new(),
            grid_refs: Vec::new(),
            grid_min_x: 0.0,
            grid_min_y: 0.0,
            grid_cell_size: 0.0,
            grid_columns: 0,
            grid_rows: 0,
        });
        if cache_used(&c).ok_or_else(limit)? > DASH_CACHE_BYTE_LIMIT {
            return Err(limit());
        }
    }
    build_stroke_grid(view, &mut c, control)?;
    Ok(c)
}
