    ];
    let weights = [
        (1.0 - fx) * (1.0 - fy),
        fx * (1.0 - fy),
        (1.0 - fx) * fy,
        fx * fy,
    ];
    let mut alpha = 0.0;
    let mut pm = [0.0; 3];
    for i in 0..4 {
        let a = p[i][3] as f64 / 255.0;
