fn dash_contains(
    _view: SceneView<'_>,
    shape: &vexel_scene::Shape,
    index: usize,
    cache: &DashCache,
    px: f64,
    py: f64,
    control: &mut dyn WorkControl,
) -> Result<bool> {
    let Some(local) = affine_map_point(shape.stroke_inverse, Point { x: px, y: py }) else {
        return Ok(false);
    };
    let Some(range) = cache.shapes.get(index) else {
        return Ok(false);
    };
    let r = shape.stroke.width * 0.5;
    let (cells, refs) = cache.grid(range)?;
    if let Some(cell) = crate::grid::job_grid_lookup(range, cells, local.x, local.y) {
        let start = cell.first as usize;
        let end = start.saturating_add(cell.count as usize).min(refs.len());
        for &encoded in &refs[start..end] {
            control
                .charge(vexel_scene::WorkKind::StrokeTest, 1)
                .map_err(crate::stopped)?;
            if encoded & STROKE_GRID_JOIN_BIT != 0 {
                let j = encoded & !STROKE_GRID_JOIN_BIT;
                let joins = &cache.joins[range.joins.first..range.joins.end().unwrap_or(0)];
                if let Some(join) = joins.get(j.saturating_sub(range.joins.first as u32) as usize) {
                    let reach = if shape.stroke.join == Linejoin::Miter {
                        r * shape.stroke.miter_limit
                    } else {
                        r
                    };
                    if (local.x - join.vertex.x).abs() <= reach
                        && (local.y - join.vertex.y).abs() <= reach
                        && join_hit(
                            join.previous,
                            join.vertex,
                            join.next,
                            local.x,
                            local.y,
                            r,
                            shape.stroke.join,
                            shape.stroke.miter_limit,
                        )
                    {
                        return Ok(true);
                    }
                }
            } else {
                let segments = &cache.segments[range.segments.first..range.segments.end().unwrap_or(0)];
                if let Some(seg) = segments.get(encoded.saturating_sub(range.segments.first as u32) as usize) {
                if segment_caps(
                    seg.edge.a,
                    seg.edge.b,
                    local.x,
                    local.y,
                    r,
                    seg.start_cap,
                    seg.end_cap,
                ) {
                    return Ok(true);
                }
                }
            }
        }
        return Ok(false);
    } else {
        return Ok(false);
    }
